SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, h.admittime, h.dischtime, e.emar_id, e.pharmacy_id, e.starttime, e.stoptime, (e.starttime - lag(e.starttime) OVER (PARTITION BY p.subject_id ORDER BY h.stay_id)) / NULLIF(lag(e.starttime) OVER (PARTITION BY p.subject_id ORDER BY h.stay_id), 0) AS initiation_rate_change FROM patients p JOIN admissions h ON p.subject_id = h.subject_id JOIN emar e ON h.subject_id = e.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 36 AND 46 AND p.anchor_year_group = 'T2DM' AND h.hadm_id IN (SELECT hadm_id FROM diagnoses_icd WHERE icd_code = '440.4') AND h.hadm_id IN (SELECT hadm_id FROM diagnoses_icd WHERE icd_code = '440.5') AND (e.starttime - lag(e.starttime) OVER (PARTITION BY p.subject_id ORDER BY h.stay_id)) / NULLIF(lag(e.starttime) OVER (PARTITION BY p.subject_id ORDER BY h.stay_id), 0) > 0.5 ORDER BY p.subject_id, h.stay_id NULLS LAST;